create extension if not exists vector;
create table public.content_documents(id uuid primary key default gen_random_uuid(),title text not null,locale text not null check(locale in('en','hi')),source_type text not null check(source_type in('staff','youtube','google_drive','partner')),source_url text,owner_organization_id uuid references public.organizations(id),status text not null default 'draft' check(status in('draft','review','published','retired')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,review_due_at timestamptz,content_hash text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.content_chunks(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.content_documents(id) on delete cascade,position integer not null,content text not null check(char_length(content) between 20 and 8000),search_vector tsvector generated always as(to_tsvector('simple',content)) stored,embedding vector(1024),embedding_model text,created_at timestamptz not null default now(),unique(document_id,position));
create table public.media_assets(id uuid primary key default gen_random_uuid(),document_id uuid references public.content_documents(id) on delete cascade,provider text not null check(provider in('youtube','google_drive')),external_id text not null,privacy_mode text not null default 'restricted',validation_status text not null default 'pending' check(validation_status in('pending','valid','invalid','permission_denied','removed')),last_checked_at timestamptz,next_check_at timestamptz not null default now(),failure_count integer not null default 0,metadata jsonb not null default '{}',unique(provider,external_id));
create table public.background_jobs(id bigint generated always as identity primary key,job_type text not null,payload jsonb not null default '{}',status text not null default 'pending' check(status in('pending','processing','completed','failed','dead_letter')),attempt_count integer not null default 0,available_at timestamptz not null default now(),locked_at timestamptz,last_error text,created_at timestamptz not null default now(),completed_at timestamptz);
create index content_chunks_search_idx on public.content_chunks using gin(search_vector);create index content_chunks_embedding_idx on public.content_chunks using hnsw(embedding vector_cosine_ops);create index media_due_idx on public.media_assets(next_check_at) where validation_status<>'removed';create index jobs_ready_idx on public.background_jobs(status,available_at) where status in('pending','failed');
alter table public.content_documents enable row level security;alter table public.content_chunks enable row level security;alter table public.media_assets enable row level security;alter table public.background_jobs enable row level security;
create policy "published documents readable" on public.content_documents for select using(status='published' and reviewed_at is not null);
create policy "published chunks readable" on public.content_chunks for select using(exists(select 1 from public.content_documents d where d.id=document_id and d.status='published' and d.reviewed_at is not null));
create policy "staff manage content documents" on public.content_documents for all using(public.is_platform_staff()) with check(public.is_platform_staff());create policy "staff manage content chunks" on public.content_chunks for all using(public.is_platform_staff()) with check(public.is_platform_staff());create policy "staff manage media" on public.media_assets for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create or replace function public.match_approved_content(p_query_text text,p_query_embedding vector(1024),p_match_count integer default 5) returns table(chunk_id uuid,title text,content text,source_url text,reviewed_at timestamptz,score double precision) language sql stable security invoker set search_path=public,pg_temp as $$select c.id,d.title,c.content,d.source_url,d.reviewed_at,(0.65*(1-(c.embedding<=>p_query_embedding))+0.35*ts_rank_cd(c.search_vector,plainto_tsquery('simple',p_query_text)))::double precision score from public.content_chunks c join public.content_documents d on d.id=c.document_id where d.status='published' and d.reviewed_at is not null and (d.review_due_at is null or d.review_due_at>now()) and c.embedding is not null order by score desc limit least(greatest(p_match_count,1),10)$$;
grant execute on function public.match_approved_content(text,vector,integer) to authenticated;
